{
  "world_id": "wld_ledgerwake",
  "name": "Ledgerwake",
  "description": "Ledgerwake is a cliffside city where every public promise is recorded on a strip of brass and hung above the streets. In this sarcastic thriller, a missing strip threatens to expose who has been quietly changing the city’s official past. The only route between the two halves is the skybridge, and its keepers insist that no one can cross without leaving a record. They are almost certainly right, which is awkward for everyone involved.",
  "locations": [
    {
      "id": "loc_brassmarket",
      "name": "Brass Market",
      "description": "A crowded terrace of clerks, brokers, and food stalls beneath thousands of dangling civic records. The latest entries are easy to find; the older ones are suspiciously hard to read."
    },
    {
      "id": "loc_skybridge",
      "name": "The Skybridge",
      "description": "A narrow, wind-battered span linking the market to the archive district across a deep ravine. Its tollhouse keeps a public ledger of every crossing, though a few pages have begun to disagree with the people listed on them."
    }
  ],
  "factions": [
    {
      "id": "fac_tallykeepers",
      "name": "The Tallykeepers",
      "description": "Custodians of the brass records and the Skybridge toll ledger. They claim their work is neutral, a useful position for people who control which version of events gets read aloud.",
      "location_ids": [
        "loc_brassmarket",
        "loc_skybridge"
      ]
    },
    {
      "id": "fac_unlisted",
      "name": "The Unlisted",
      "description": "Residents whose names have vanished from civic records, leaving them unable to claim property, testify, or prove they exist to anyone who prefers paperwork to people.",
      "location_ids": [
        "loc_brassmarket"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_brassrecord",
      "statement": "A public promise becomes legally binding only when its brass strip is displayed in the market.",
      "category": "social"
    },
    {
      "id": "rul_crossingmark",
      "statement": "Every passage over the Skybridge leaves a visible mark in the toll ledger, even when the name entered there is false.",
      "category": "other"
    },
    {
      "id": "rul_recordweight",
      "statement": "A person erased from every civic record loses the right to own property, but not the ability to alter the records that erased them.",
      "category": "metaphysics"
    }
  ],
  "history": [
    {
      "id": "evt_firstledger",
      "name": "The First Ledger",
      "description": "After a succession dispute nearly split the city, its leaders began recording public promises on brass. The system reduced arguments by making them considerably more expensive to deny.",
      "era": "Founding years",
      "location_ids": [
        "loc_brassmarket"
      ]
    },
    {
      "id": "evt_missingpage",
      "name": "The Missing Page",
      "description": "A page disappeared from the Skybridge toll ledger, and several witnesses recall crossing on a night when the official record says the bridge was closed.",
      "era": "Present day",
      "location_ids": [
        "loc_skybridge"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_erasednames",
      "name": "The Names That Return",
      "description": "The Unlisted want the missing ledger page restored as proof that the city has been deleting its residents. The Tallykeepers fear that revealing the page will expose a deliberate breach in the system they are sworn to preserve.",
      "faction_ids": [
        "fac_tallykeepers",
        "fac_unlisted"
      ]
    }
  ]
}
